function socialProofDelay(){return 8000+Math.floor(Math.random()*7001)}
function formatProofAge(proof){const recorded=proof?.created_at?Math.floor((Date.now()-new Date(proof.created_at).getTime())/1000):Number(proof?.time_offset_seconds);const value=Math.max(1,Number(recorded)||1);if(value<60)return`${value} second${value===1?'':'s'} ago`;const minutes=Math.floor(value/60);if(minutes<60)return`${minutes} minute${minutes===1?'':'s'} ago`;const hours=Math.floor(minutes/60);if(hours<24)return`${hours} hour${hours===1?'':'s'} ago`;const days=Math.floor(hours/24);return`${days} day${days===1?'':'s'} ago`}
