function normalizePhone(value){const digits=String(value||'').trim();if(!/^\d{10,15}$/.test(digits))return null;if(digits.startsWith('234')&&digits.length===13)return`+${digits}`;if(digits.startsWith('0')&&digits.length===11)return`+234${digits.slice(1)}`;if(digits.length===10)return`+234${digits}`;return`+${digits}`}
