async function loadLiveData(){if(!sb)return;const[propertiesResult,transactionsResult,staysResult,paymentsResult,statsResult,networkResult]=await Promise.all([sb.from('properties').select('*').order('created_at',{ascending:false}),sb.from('transactions').select('*').order('created_at',{ascending:false}).limit(100),sb.from('referred_stays').select('*').order('created_at',{ascending:false}),sb.from('stay_payments').select('*').order('created_at',{ascending:true}),sb.rpc('get_my_dashboard_stats'),sb.rpc('get_my_network_members')]);if(!propertiesResult.error)sample.properties=(propertiesResult.data||[]).map(hydrateProperty);if(!transactionsResult.error)sample.transactions=(transactionsResult.data||[]).map(t=>({...t,id:`TXN-${t.id}`,amount:Number(t.amount||0),date:new Date(t.created_at).toLocaleString('en-NG',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}),method:t.type==='withdrawal'?'Bank transfer':'Commission wallet'}));if(!staysResult.error){const payments=paymentsResult.error?[]:(paymentsResult.data||[]);sample.bookings=(staysResult.data||[]).map(stay=>({id:stay.id,property_id:stay.property_id,ambassador:stay.referral_code,referral_code:stay.referral_code,guest_name:stay.guest_name,guest_phone:stay.guest_phone,check_in:stay.check_in,nights:stay.nights,room:stay.room_name,payments:payments.filter(p=>p.stay_id===stay.id).map(p=>({amount:Number(p.amount||0),method:p.payment_method,note:p.note})),booking_value:Number(stay.total_paid||0),commission_amount:Number(stay.commission_due||0),status:stay.status,settlement_status:stay.settlement_status,code:stay.stay_reference}))}dashboardStats=statsResult.error?{}:(statsResult.data||{});networkMembers=networkResult.error?[]:(networkResult.data||[]);if(statsResult.error)console.info('Dashboard aggregates require database-repair-and-sample.sql.');}
async function loadProfile(user){const{data:profile,error}=await sb.from('profiles').select('*').eq('id',user.id).single();if(error){console.error('Profile load failed',error);toast(error.code==='PGRST205'?'Database setup is incomplete':'Unable to load your profile');return false}const authPhone=user.user_metadata?.phone||profile.phone;if(authPhone&&profile.phone!==authPhone){const{error:phoneSyncError}=await sb.from('profiles').update({phone:authPhone}).eq('id',user.id);if(phoneSyncError)console.warn('Unable to sync sign-in phone to profile',phoneSyncError)}currentUser={...profile,phone:authPhone,membership_plan:membershipPlanKey(user.user_metadata?.membership_plan||profile.membership_plan||selectedMembershipPlan)};currentRole=profile.role;document.body.classList.toggle('manager-mode',currentRole==='manager');await loadLiveData();showApp();return true}
async function restoreSession(){if(demo){const saved=localStorage.getItem('tc-role');if(saved)roleLogin(saved);else if(startupAuthMode)openAuth(startupAuthMode,startupPlan);else if(!authEntryRequested)showPublicHomepage();return}const{data,error}=await sb.auth.getSession();if(error){if(!authEntryRequested)showPublicHomepage();return toast(friendlyAuthError(error))}if(data.session)await loadProfile(data.session.user);else if(startupAuthMode)openAuth(startupAuthMode,startupPlan);else if(!authEntryRequested)showPublicHomepage()}
