function confirmReferralOmission(stepIndex){const prompt=$('#referralOmissionPrompt'),copy=referralOmissionSteps[stepIndex],previousFocus=document.activeElement;$('#referralPromptStep').textContent=copy.step;$('#referralPromptTitle').textContent=copy.title;$('#referralPromptCopy').textContent=copy.copy;$('#referralPromptBack').textContent=copy.back;$('#referralPromptContinue').textContent=copy.proceed;prompt.classList.remove('hidden');prompt.focus();return new Promise(resolve=>{const back=$('#referralPromptBack'),proceed=$('#referralPromptContinue');let settled=false;const finish=value=>{if(settled)return;settled=true;prompt.classList.add('hidden');prompt.onkeydown=null;back.onclick=null;proceed.onclick=null;(value?previousFocus:$('#signupReferralNumber'))?.focus();resolve(value)};back.onclick=()=>finish(false);proceed.onclick=()=>finish(true);prompt.onkeydown=event=>{if(event.key==='Escape'){event.preventDefault();finish(false)}else if(event.key==='Tab'){const first=back,last=proceed;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}};back.focus()})}
