async function checkPasswordOnlySettings(){if(demo||!sb){passwordOnlyReady=true;return true}try{const response=await fetch(`${cfg.supabaseUrl}/auth/v1/settings`,{headers:{apikey:cfg.supabasePublishableKey}}),settings=await response.json();passwordOnlyReady=settings.email!==false&&settings.mailer_autoconfirm===true;$('#authNote').classList.toggle('auth-warning',!passwordOnlyReady);if(settings.email===false)$('#authNote').textContent='Enable the Email provider. Keep Phone disabled; the hook blocks all email.';else if(settings.mailer_autoconfirm!==true)$('#authNote').textContent='Turn off Confirm email, save changes, then refresh.';else $('#authNote').textContent='';return passwordOnlyReady}catch(error){passwordOnlyReady=false;$('#authNote').textContent='Unable to verify Supabase Auth settings. Refresh and try again.';$('#authNote').classList.add('auth-warning');console.warn('Unable to check password-only Auth settings',error);return false}}
