function propertyMatches(p){const query=propertyFilters.query.toLowerCase(),haystack=[p.name,p.city,p.state,p.lga,p.location,p.address,p.description,...(p.amenities||[])].join(' ').toLowerCase();return(!query||haystack.includes(query))&&(!propertyFilters.state||stateSlug(p.state)===stateSlug(propertyFilters.state))&&(!propertyFilters.lga||locationSlug(p.lga)===locationSlug(propertyFilters.lga))&&(!propertyFilters.location||locationSlug(p.location)===locationSlug(propertyFilters.location))}
