function buildBinary(depth=5){let id=1;const names=['You','Aisha','Usman','Grace','Kabiru','Fatima','Samuel','Hauwa','John','Ruth','Aliyu','Mary','Ibrahim','Zainab','Peter','Musa','Amina','David','Sarah','Yusuf','Mercy','Daniel','Ladi','Sani','Halima','Victor','Joy','Abba','Esther','Bello','Paul'];function node(level){if(level>depth)return null;const n={id:id,name:names[id-1]||`Member ${id}`,level,bookings:Math.max(1,13-level*2+(id%4))};id++;n.left=node(level+1);n.right=node(level+1);return n}return node(1)}
function buildDatabaseTree(){const rootId=String(currentUser?.id||'root'),root={id:rootId,name:'You',level:0,bookings:Number(dashboardStats.bookings||0),left:null,right:null},nodes=new Map([[rootId,root]]);networkMembers.slice().sort((a,b)=>Number(a.depth||0)-Number(b.depth||0)).forEach(member=>{const node={id:String(member.member_id),name:member.full_name,level:Number(member.depth||1),bookings:Number(member.booking_count||0),left:null,right:null},parent=nodes.get(String(member.parent_id))||root,preferred=member.branch==='right'?'right':'left';if(!parent[preferred])parent[preferred]=node;else if(!parent[preferred==='left'?'right':'left'])parent[preferred==='left'?'right':'left']=node;nodes.set(node.id,node)});return root}
function renderTree(){const root=demo?buildBinary(5):buildDatabaseTree(),canvas=$('#referralTree');if(!canvas)return;const W=1500,H=610,levelGap=116,nodes=[],lines=[];function walk(n,x,y,spread){if(!n)return;nodes.push({n,x,y});if(n.left){lines.push([x,y,x-spread,y+levelGap]);walk(n.left,x-spread,y+levelGap,spread/2)}if(n.right){lines.push([x,y,x+spread,y+levelGap]);walk(n.right,x+spread,y+levelGap,spread/2)}}walk(root,W/2,65,350);canvas.style.width=W+'px';canvas.style.height=H+'px';canvas.innerHTML=`<svg width="${W}" height="${H}">${lines.map(l=>`<path d="M${l[0]} ${l[1]+28} C${l[0]} ${l[1]+65},${l[2]} ${l[3]-65},${l[2]} ${l[3]-28}" fill="none" stroke="rgba(91,111,249,.32)" stroke-width="2"/>`).join('')}</svg>`+nodes.map(({n,x,y})=>`<button class="tree-node ${n===root?'root':''}" style="left:${x}px;top:${y}px" onclick="showMember('${String(n.name).replace(/'/g,'')}',${n.level},${n.bookings})"><span class="avatar-mini">${initials(n.name)}</span><b>${esc(n.name)}</b><small>${n===root?'Your account':`Level ${n.level} • ${n.bookings} bookings`}</small></button>`).join('');applyTreeTransform()}
