function managerBookingRow(b){const p=propertyById(b.property_id)||{name:'Property'},paid=(b.payments||[]).reduce((n,x)=>n+Number(x.amount||0),0);return `<article class="booking-row glass-card stay-row"><div class="item-icon">🏨</div><div class="item-copy"><b>${esc(b.guest_name)} • ${esc(b.code)}</b><small>${esc(p.name)} • Code ${esc(b.referral_code)} • ${esc(b.ambassador)}<br>${b.nights} night(s) • ${esc(b.room||'Room')} • Paid ${naira(paid)}</small></div><span class="status ${b.status}">${b.status}</span><div class="manager-actions"><button onclick="openSheet('stayDetails',${b.id})">View</button>${b.status==='active'?`<button onclick="openSheet('addPayment',${b.id})">Add payment</button><button onclick="openSheet('extendStay',${b.id})">Extend</button><button onclick="completeStay(${b.id})">Complete</button>`:''}</div></article>`}
function renderManagerBookings(list){$('#managerBookingList').innerHTML=list.map(managerBookingRow).join('')}
function renderManagerProperties(list){$('#managerPropertyList').innerHTML=list.map(p=>`<article class="manager-property glass-card"><div class="manager-property-top"><div class="manager-thumb" style="background-image:url('${esc(p.image)}')"></div><div class="item-copy"><b>${esc(p.name)}</b><small>${esc(p.city)} • ${Number(p.rooms||0)} rooms • ${Number(p.occupancy||0)}% occupancy</small><div class="property-bottom"><span class="status confirmed">Active</span><b>${Number(p.commission_rate||0)}% commission</b></div></div></div><div class="manager-actions"><button onclick="openSheet('editProperty',${p.id})">Edit listing</button><button onclick="toast('Analytics opened')">Analytics</button><button onclick="openPropertyDetails(${p.id})">Preview</button></div></article>`).join('')}
function renderProfile(){const u=currentUser||sample.users.ambassador,s=dashboardStats;$('#profileAvatar').textContent=initials(u.full_name);$('#profileName').textContent=u.full_name;$('#profileRole').textContent=currentRole==='manager'?'Property Partner':`${membershipPlanName(u.membership_plan)} plan • ${u.rank||'Elite Ambassador'}`;$('#referralCodeText').textContent=u.referral_code||'TC-MEMBER';$('#payoutAccountSummary').textContent=u.bank_account_number?`${u.bank_name||'Bank'} •••• ${u.bank_account_number.slice(-4)}`:'Add a payout account';$('#profileMetrics').innerHTML=currentRole==='manager'?`<div><b>${s.properties||0}</b><span>Properties</span></div><div><b>${s.bookings||0}</b><span>Bookings</span></div><div><b>${Number(s.rating||0).toFixed(1)}</b><span>Rating</span></div>`:`<div><b>${s.direct_referrals??u.direct_referrals??0}</b><span>Directs</span></div><div><b>${s.bookings??u.total_bookings??0}</b><span>Bookings</span></div><div><b>${Number(s.rating||0).toFixed(1)}</b><span>Rating</span></div>`}
function updateBooking(id,status){const b=sample.bookings.find(x=>x.id===id);if(!b)return;b.status=status;renderManager();toast(`Booking ${status}`)}
function convertReferral(id){const r=sample.referrals.find(x=>x.id===id);openSheet('logReferral',id)}
function openCustom(html){$('#sheetContent').innerHTML=html;$('#sheetBackdrop').classList.remove('hidden');$('#modalSheet').classList.remove('hidden');document.body.classList.add('sheet-open')}
function closeSheet(){if(propertyMap){propertyMap.remove();propertyMap=null;propertyMarker=null}if(propertyDetailMap){propertyDetailMap.remove();propertyDetailMap=null}$('#sheetBackdrop').classList.add('hidden');$('#modalSheet').classList.add('hidden');document.body.classList.remove('sheet-open')}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function checked(list,value){return (list||[]).includes(value)?'checked':''}
function propertyStateOptions(selected=''){return Object.keys(nigeriaStateLgas).map(slug=>{const label=titleCase(slug);return`<option value="${esc(label)}" ${stateSlug(selected)===slug?'selected':''}>${esc(label)}</option>`}).join('')}
function propertyLgaOptions(state,selected=''){return(nigeriaStateLgas[stateSlug(state)]||[]).map(slug=>{const label=titleCase(slug);return`<option value="${esc(label)}" ${locationSlug(selected)===slug?'selected':''}>${esc(label)}</option>`}).join('')}
function propertyForm(p={},id=0){const amenities=['WiFi','Pool','Spa','Restaurant','Hall','Gym','Parking','Breakfast','Airport Pickup','Family Rooms','Ocean View','Mountain View'];const incentives=['5% discount','Complimentary breakfast','Free welcome drink','Room upgrade'];const selectedIncentives=p.incentives||([p.incentive].filter(Boolean)),state=p.state==='FCT'?'Abuja':p.state||'',lga=p.lga||'',existingPictures=propertyPictureUrls(p);return `<h2 class="sheet-title">${id?'Edit property':'Add New Property'}</h2><p class="sheet-copy">Add a searchable State, LGA and neighbourhood, then place the pin on the property's exact entrance.</p><form class="form-grid property-form" onsubmit="saveProperty(event,${id})"><section class="form-section location-form-section"><div class="form-section-title"><span>1</span><div><h3>Searchable location</h3><p>Guests use these fields to discover your property.</p></div></div><label class="field">Property name<input id="propName" value="${esc(p.name||'')}" required></label><div class="form-two"><label class="field">State<select id="propState" onchange="syncPropertyLgas(this.value)" required><option value="">Select state</option>${propertyStateOptions(state)}</select></label><label class="field">LGA<select id="propLga" required><option value="">Select LGA</option>${propertyLgaOptions(state,lga)}</select></label></div><div class="form-two"><label class="field">City<input id="propCity" value="${esc(p.city||'')}" placeholder="e.g. Lagos" required></label><label class="field">Location / neighbourhood<input id="propLocation" value="${esc(p.location||'')}" placeholder="e.g. Victoria Island" required></label></div><label class="field">Exact street address<input id="propAddress" value="${esc(p.address||'')}" placeholder="Building number, street and landmark" required></label><label class="field">Short description<textarea id="propDescription" rows="3" placeholder="What makes this property special?">${esc(p.description||'')}</textarea></label><label class="field">Number of rooms<input id="propRooms" type="number" min="1" value="${p.rooms||''}" required></label></section><section class="form-section"><div class="form-section-title"><span>2</span><div><h3>Room price and reward</h3><p>Show the range and Ambassador commission.</p></div></div><div class="form-two"><label class="field">Least expensive (₦)<input id="propMinPrice" type="number" min="0" value="${p.min_price||p.price||''}" required></label><label class="field">Most expensive (₦)<input id="propMaxPrice" type="number" min="0" value="${p.max_price||p.price||''}" required></label></div><label class="field">Ambassador commission %<input id="propRate" type="number" min="0" max="100" value="${p.commission_rate||''}" required></label></section><section class="form-section"><h3>Amenities</h3><div class="choice-grid">${amenities.map(item=>`<label class="check-card"><input type="checkbox" name="amenities" value="${esc(item)}" ${checked(p.amenities,item)}><span>${esc(item)}</span></label>`).join('')}</div></section><section class="form-section"><h3>Guest incentives</h3><div class="choice-grid incentives">${incentives.map(item=>`<label class="check-card"><input type="checkbox" name="incentives" value="${esc(item)}" ${checked(selectedIncentives,item)}><span>${esc(item)}</span></label>`).join('')}</div><div id="extraIncentives">${(p.extra_incentives||[]).map(item=>`<label class="field removable-field">Other incentive<input name="extraIncentive" value="${esc(item)}"><button type="button" onclick="this.parentElement.remove()">×</button></label>`).join('')}</div><button class="add-inline" type="button" onclick="addIncentiveField()">＋ Add another incentive</button></section><section class="form-section"><h3>Property pictures</h3><label class="upload-box">Choose property images<input id="propPictures" type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" multiple><span id="pictureLabel">${existingPictures.length?existingPictures.length+' existing picture(s)':'No file chosen'}</span><small>JPG, PNG, WebP, GIF or AVIF • up to 8 files • 8 MB each</small></label><div id="picturePreview" class="picture-preview">${existingPictures.map(url=>`<img src="${esc(url)}" alt="Existing property picture">`).join('')}</div></section><section class="form-section exact-map-section"><div class="form-section-title"><span>3</span><div><h3>Exact map location</h3><p>Tap or drag the pin to the guest entrance—not just the city centre.</p></div></div><button class="gps-button" type="button" onclick="useCurrentLocation()">⌖ Use my current GPS location</button><div id="propertyMap" class="property-map"></div><div class="coordinate-readout"><label>LATITUDE<input id="propLat" type="number" step="any" value="${p.latitude||9.0765}" readonly></label><label>LONGITUDE<input id="propLng" type="number" step="any" value="${p.longitude||7.3986}" readonly></label></div><p class="map-accuracy-note">The saved pin will appear on the public property page and open directly in Maps.</p></section><button class="primary-btn">${id?'Update':'Publish'} property <span>→</span></button></form>`}
function syncPropertyLgas(state){const select=$('#propLga');if(!select)return;select.innerHTML='<option value="">Select LGA</option>'+propertyLgaOptions(state);select.disabled=!state}
function initPropertyMap(p={}){setTimeout(()=>{const el=$('#propertyMap');if(!el||!window.L)return;const lat=Number(p.latitude||9.0765),lng=Number(p.longitude||7.3986);propertyMap=L.map(el).setView([lat,lng],p.latitude?16:11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(propertyMap);propertyMarker=L.marker([lat,lng],{draggable:true}).addTo(propertyMap).bindTooltip('Exact property entrance',{permanent:false});const sync=ll=>{$('#propLat').value=ll.lat.toFixed(6);$('#propLng').value=ll.lng.toFixed(6)};propertyMap.on('click',event=>{propertyMarker.setLatLng(event.latlng);sync(event.latlng)});propertyMarker.on('dragend',()=>sync(propertyMarker.getLatLng()));setTimeout(()=>propertyMap.invalidateSize(),100)},80)}
function openMembershipCard(){const u=currentUser||sample.users.ambassador,roleLabel=currentRole==='manager'?'PROPERTY PARTNER':`${membershipPlanName(u.membership_plan).toUpperCase()} AMBASSADOR`;openCustom(`<h2 class="sheet-title">Your Membership Card</h2><p class="sheet-copy">Your digital ${currentRole==='manager'?'property partner':'ambassador'} credential.</p><div id="membershipCard" class="membership-card"><div class="card-top"><b>THE COMMISSION</b><span>${esc(u.full_name).toUpperCase()}</span></div><div class="card-watermark">TC</div><div class="card-role">${roleLabel}</div><div class="card-code">${esc(u.referral_code)}</div><div id="membershipQr" class="membership-qr"></div></div><button class="primary-btn card-download" onclick="downloadMembershipCard()">Download as PNG <span>↓</span></button>`);setTimeout(()=>{const q=$('#membershipQr');if(q&&window.QRCode)new QRCode(q,{text:`https://thecommission.app/r/${u.referral_code}`,width:76,height:76,colorDark:'#111',colorLight:'#fff'})},30)}
function openReferralCode(){const u=currentUser||sample.users.ambassador;const link=`https://thecommission.app/r/${u.referral_code}`;openCustom(`<h2 class="sheet-title">Your Referral Code</h2><p class="sheet-copy">Share this code to grow your network and earn from eligible bookings.</p><div class="referral-code-box"><b>${esc(u.referral_code)}</b><button onclick="copyReferralCode()">▣ Copy</button></div><button class="whatsapp-btn" onclick="shareReferralWhatsApp()">◉ Share on WhatsApp</button><button class="soft-btn share-native" onclick="shareReferralNative()">Share using another app</button><small class="share-link">${link}</small>`)}
function activeUser(){return currentUser||sample.users[currentRole]||sample.users.ambassador}
function syncUser(payload){Object.assign(activeUser(),payload);if(sample.users[currentRole])Object.assign(sample.users[currentRole],payload)}
function transactionTypeLabel(type){return ({direct:'Direct commission',network:'Network bonus',withdrawal:'Wallet withdrawal',pending:'Pending credit',adjustment:'Wallet adjustment'})[type]||'Wallet transaction'}
function openTransactionReceipt(index){const t=sample.transactions[index];if(!t)return;const u=activeUser(),incoming=t.amount>0,status=t.status||'paid',reference=t.id||`TXN-${String(index+1).padStart(6,'0')}`,destination=incoming?'Commission wallet':`${u.bank_name||'Payout bank'} •••• ${(u.bank_account_number||'').slice(-4)}`;openCustom(`<h2 class="sheet-title">Transaction receipt</h2><p class="sheet-copy">A complete record of this wallet activity.</p><article class="receipt-card" id="transactionReceipt"><div class="receipt-orb receipt-orb-a"></div><div class="receipt-orb receipt-orb-b"></div><header class="receipt-brand"><b><span>TC</span> THE COMMISSION</b><em class="receipt-status ${status}">${status==='paid'?'✓':'◷'} ${esc(status)}</em></header><div class="receipt-main"><div class="receipt-icon">${incoming?'↗':'↙'}</div><small>${incoming?'AMOUNT RECEIVED':'AMOUNT SENT'}</small><h1>${naira(Math.abs(t.amount))}</h1><p>${esc(t.title)}</p></div><div class="receipt-details"><div><span>Description</span><b>${esc(t.description)}</b></div><div><span>Reference</span><b>${esc(reference)}</b></div><div><span>Date</span><b>${esc(t.date)}</b></div><div><span>Transaction type</span><b>${transactionTypeLabel(t.type)}</b></div><div><span>Payment method</span><b>${esc(t.method||'Commission wallet')}</b></div><div><span>${incoming?'Destination':'Paid to'}</span><b>${esc(destination)}</b></div><div><span>Status</span><b class="${status==='paid'?'positive':'pending-text'}">${status==='paid'?'Successful':esc(status)}</b></div></div><footer>Generated for ${esc(u.full_name)} • ${esc(u.referral_code||'TC MEMBER')}</footer></article><div class="receipt-actions"><button class="soft-btn" onclick="copyTransactionReference('${esc(reference)}')">▣ Copy reference</button><button class="primary-btn" onclick="downloadTransactionReceipt('${esc(reference)}')">Download receipt <span>↓</span></button></div>`)}
function openWithdraw(){const u=activeUser(),hasBank=Boolean(u.bank_name&&u.bank_account_number);openCustom(`<h2 class="sheet-title">Withdraw funds</h2><p class="sheet-copy">Send available commission to your verified payout account.</p><article class="withdraw-balance liquid-card"><small>AVAILABLE BALANCE</small><h1>${naira(u.balance)}</h1><span>Minimum withdrawal: ₦1,000</span></article>${hasBank?`<article class="withdraw-destination"><div class="bank-mark">▣</div><div><small>PAYOUT DESTINATION</small><b>${esc(u.bank_name)}</b><span>${esc(u.bank_account_name||u.full_name)} • •••• ${u.bank_account_number.slice(-4)}</span></div><button type="button" onclick="openPayoutAccount()">Change</button></article><form class="form-grid" onsubmit="submitWithdrawal(event)"><label class="field">Amount to withdraw (₦)<input id="withdrawAmount" type="number" inputmode="decimal" min="1000" max="${Number(u.balance)}" step="100" placeholder="0" required oninput="updateWithdrawalSummary(this.value)"></label><div class="withdraw-summary"><div><span>You request</span><b id="withdrawRequest">₦0</b></div><div><span>Transfer fee</span><b>₦0</b></div><div><span>You receive</span><b id="withdrawReceive">₦0</b></div></div><button class="primary-btn">Request withdrawal <span>→</span></button><small class="form-note">Withdrawals are reviewed and usually arrive within 1–2 business days.</small></form>`:`<div class="empty-bank-state"><div>🏦</div><h3>Add a payout account first</h3><p>Your bank details are required before you can withdraw commission.</p><button class="primary-btn" onclick="openPayoutAccount()">Add payout account <span>→</span></button></div>`}`)}
function openPayoutAccount(){const u=activeUser(),hasBank=Boolean(u.bank_name&&u.bank_account_number),banks=['Access Bank','Citibank','Ecobank','Fidelity Bank','First Bank','FCMB','GTBank','Heritage Bank','Jaiz Bank','Keystone Bank','Polaris Bank','Stanbic IBTC','Sterling Bank','UBA','Union Bank','Unity Bank','Wema Bank','Zenith Bank'];openCustom(`<h2 class="sheet-title">Payout account</h2><p class="sheet-copy">Commission withdrawals will be sent to this verified Nigerian bank account.</p>${hasBank?`<article class="bank-account-preview"><div class="bank-preview-top"><span>PRIMARY PAYOUT ACCOUNT</span><i>✓ VERIFIED</i></div><div class="bank-preview-chip">▦</div><h2>${esc(u.bank_name)}</h2><p>•••• •••• ${u.bank_account_number.slice(-4)}</p><b>${esc(u.bank_account_name||u.full_name)}</b></article>`:''}<form class="form-grid payout-form" onsubmit="savePayoutAccount(event)"><label class="field">Bank<select id="payoutBank" required><option value="">Select your bank</option>${banks.map(x=>`<option ${u.bank_name===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Account number<input id="payoutNumber" inputmode="numeric" pattern="[0-9]{10}" maxlength="10" value="${esc(u.bank_account_number||'')}" placeholder="10-digit account number" required></label><label class="field">Account name<input id="payoutName" value="${esc(u.bank_account_name||u.full_name||'')}" placeholder="Name shown on the account" required></label><div class="security-note"><span>⌾</span><p><b>Your payout details are protected</b>We only display the last four digits after saving.</p></div><button class="primary-btn">${hasBank?'Update':'Save'} payout account <span>✓</span></button></form>`)}
function openEditProfile(){const u=activeUser();openCustom(`<h2 class="sheet-title">Edit profile</h2><p class="sheet-copy">Keep your personal information accurate for account verification and payouts.</p><div class="edit-profile-intro"><div>${initials(u.full_name)}</div><span><b>${esc(u.full_name)}</b><small>${esc(u.rank||'Commission member')}</small></span></div><form class="form-grid" onsubmit="saveProfile(event)"><label class="field">Full name<input id="editFullName" value="${esc(u.full_name)}" autocomplete="name" required></label><label class="field">Sign-in phone number<input type="tel" value="${esc(u.phone||'')}" autocomplete="tel" disabled></label><label class="field">City<input id="editCity" value="${esc(u.city||'')}" autocomplete="address-level2" required></label><label class="field">Membership ID<input value="${esc(u.referral_code||'')}" disabled></label><div class="security-note"><span>✓</span><p><b>Identity details</b>Your sign-in number, membership ID and account type require verification before they can change.</p></div><button class="primary-btn">Save profile changes <span>✓</span></button></form>`)}
function openWalletReport(){const tx=sample.transactions,inflow=tx.filter(t=>t.amount>0).reduce((n,t)=>n+t.amount,0),outflow=Math.abs(tx.filter(t=>t.amount<0).reduce((n,t)=>n+t.amount,0)),direct=tx.filter(t=>t.type==='direct').reduce((n,t)=>n+t.amount,0),network=tx.filter(t=>t.type==='network').reduce((n,t)=>n+t.amount,0),largest=Math.max(direct,network,1);openCustom(`<h2 class="sheet-title">Wallet report</h2><p class="sheet-copy">Your earnings and payout activity at a glance.</p><article class="report-hero liquid-card"><small>NET WALLET ACTIVITY</small><h1>${naira(inflow-outflow)}</h1><p>${sample.transactions.length} transactions in this report</p></article><div class="report-metrics"><article><span>Total earned</span><b class="positive">${naira(inflow)}</b></article><article><span>Withdrawn</span><b>${naira(outflow)}</b></article><article><span>Available now</span><b>${naira(activeUser().balance)}</b></article></div><article class="report-breakdown glass-card"><div class="row"><div><small>EARNINGS MIX</small><h3>Commission sources</h3></div><b>${naira(direct+network)}</b></div><label><span>Direct commission</span><b>${naira(direct)}</b></label><div class="report-track"><i style="width:${direct/largest*100}%"></i></div><label><span>Network bonus</span><b>${naira(network)}</b></label><div class="report-track network"><i style="width:${network/largest*100}%"></i></div></article><div class="report-list">${tx.map(t=>`<div><span><b>${esc(t.title)}</b><small>${esc(t.date)}</small></span><strong class="${t.amount>0?'positive':'negative'}">${t.amount>0?'+':''}${naira(t.amount)}</strong></div>`).join('')}</div><button class="primary-btn report-download" onclick="downloadWalletReport()">Download CSV report <span>↓</span></button>`)}
function openSheet(type,id){if(type==='booking'||type==='referralCode'||type==='invite'){openReferralCode()}else if(type==='withdraw'){openWithdraw()}else if(type==='bank'){openPayoutAccount()}else if(type==='analytics'){openWalletReport()}else if(type==='editProfile'){openEditProfile()}else if(type==='notifications'){const items=sample.transactions.slice(0,5);openCustom(`<h2 class="sheet-title">Notifications</h2><p class="sheet-copy">Recent verified activity on your account.</p><div class="stack">${items.map(item=>`<article class="glass-card payment-line"><div><b>${esc(item.title)}</b><small>${esc(item.description)} • ${esc(item.date)}</small></div><strong class="${item.amount>=0?'positive':'negative'}">${item.amount>=0?'+':''}${naira(item.amount)}</strong></article>`).join('')||'<div class="empty-state">No notifications yet.</div>'}</div>`)}else if(type==='settings'){const u=activeUser();openCustom(`<h2 class="sheet-title">Account settings</h2><p class="sheet-copy">Manage the details that control your profile and payouts.</p><article class="clay-card" style="padding:16px"><div class="row"><span>Account</span><b>${esc(u.full_name)}</b></div><div class="row" style="margin-top:10px"><span>Membership</span><b>${membershipPlanName(u.membership_plan)}</b></div><div class="row" style="margin-top:10px"><span>Sign-in phone</span><b>${esc(u.phone||'Not set')}</b></div></article><div class="form-two" style="margin-top:14px"><button class="soft-btn" type="button" onclick="openEditProfile()">Edit profile</button><button class="soft-btn" type="button" onclick="openPayoutAccount()">Payout account</button></div>`)}else if(type==='managerReport'){const revenue=sample.bookings.reduce((sum,stay)=>sum+Number(stay.booking_value||0),0),due=sample.bookings.filter(stay=>stay.status==='completed'&&stay.settlement_status==='due').reduce((sum,stay)=>sum+Number(stay.commission_amount||0),0);openCustom(`<h2 class="sheet-title">Property performance</h2><p class="sheet-copy">A live summary of referred stays across your portfolio.</p><div class="report-metrics"><article><span>Referred revenue</span><b>${naira(revenue)}</b></article><article><span>Commission due</span><b>${naira(due)}</b></article><article><span>Total stays</span><b>${sample.bookings.length}</b></article></div>`)}else if(type==='newReferredStay'){openCustom(`<h2 class="sheet-title">Open referred stay</h2><p class="sheet-copy">The guest only gives reception a permanent Ambassador code. Record the stay and continue with the hotel’s normal payment process.</p><form class="form-grid" onsubmit="saveNewStay(event)"><label class="field">Permanent Ambassador code<input id="stayReferralCode" placeholder="e.g. TC-SARKI-204" required oninput="previewAmbassadorCode(this.value)"></label><div id="ambassadorCodePreview" class="code-preview">Enter a code to identify the Ambassador.</div><label class="field">Property<select id="stayProperty">${sample.properties.filter(p=>p.manager_id==='m1').map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><div class="form-two"><label class="field">Guest name<input id="stayGuestName" required></label><label class="field">Guest phone<input id="stayGuestPhone" required></label></div><div class="form-two"><label class="field">Check-in<input id="stayCheckIn" type="date" required></label><label class="field">Initial nights<input id="stayNights" type="number" min="1" value="1" required></label></div><label class="field">Room / category<input id="stayRoom" placeholder="e.g. Executive Room" required></label><div class="form-two"><label class="field">Amount received now<input id="stayAmount" type="number" min="0" value="0" required></label><label class="field">Payment method<select id="stayMethod"><option>Cash</option><option>Hotel transfer</option><option>POS</option><option>Corporate account</option><option>Pay later</option></select></label></div><button class="primary-btn">Open referred stay <span>→</span></button></form>`)}else if(type==='addPayment'){const b=sample.bookings.find(x=>x.id===id);openCustom(`<h2 class="sheet-title">Add payment</h2><p class="sheet-copy">${b.guest_name} • ${b.code}. Record only money actually received by the hotel.</p><form class="form-grid" onsubmit="saveStayPayment(event,${id})"><label class="field">Amount received<input id="paymentAmount" type="number" min="1" required></label><label class="field">Payment method<select id="paymentMethod"><option>Cash</option><option>Hotel transfer</option><option>POS</option><option>Corporate account</option></select></label><label class="field">Note<input id="paymentNote" placeholder="e.g. balance for current stay"></label><button class="primary-btn">Add payment <span>＋</span></button></form>`)}else if(type==='extendStay'){const b=sample.bookings.find(x=>x.id===id);openCustom(`<h2 class="sheet-title">Extend stay</h2><p class="sheet-copy">Add the extra nights and any payment received. The same Ambassador code remains attached.</p><form class="form-grid" onsubmit="saveStayExtension(event,${id})"><label class="field">Additional nights<input id="extensionNights" type="number" min="1" value="1" required></label><label class="field">Amount received<input id="extensionAmount" type="number" min="0" value="0" required></label><label class="field">Payment method<select id="extensionMethod"><option>Cash</option><option>Hotel transfer</option><option>POS</option><option>Corporate account</option><option>Pay later</option></select></label><button class="primary-btn">Extend stay <span>→</span></button></form>`)}else if(type==='stayDetails'){const b=sample.bookings.find(x=>x.id===id),p=propertyById(b.property_id);openCustom(`<h2 class="sheet-title">${b.guest_name}</h2><p class="sheet-copy">${p.name} • ${b.code}</p><article class="clay-card stay-detail-card"><div class="row"><span>Ambassador</span><b>${b.ambassador}</b></div><div class="row"><span>Permanent code</span><b>${b.referral_code}</b></div><div class="row"><span>Nights</span><b>${b.nights}</b></div><div class="row"><span>Total paid</span><b>${naira(b.booking_value)}</b></div><div class="row"><span>Commission generated</span><b>${naira(b.commission_amount)}</b></div><div class="row"><span>Settlement</span><b>${b.settlement_status}</b></div></article><h3>Payment history</h3><div class="stack">${(b.payments||[]).map(x=>`<article class="glass-card payment-line"><div><b>${naira(x.amount)}</b><small>${x.method} • ${x.note||'Payment'}</small></div></article>`).join('')||'<div class="empty-state">No payment recorded.</div>'}</div>`)}else if(type==='settlementStatement'){const due=sample.bookings.filter(b=>b.status==='completed'&&b.settlement_status==='due');openCustom(`<h2 class="sheet-title">Weekly settlement statement</h2><p class="sheet-copy">Only completed referred stays awaiting settlement are included.</p><div class="stack">${due.map(b=>`<article class="glass-card settlement-line"><div><b>${b.guest_name} • ${propertyById(b.property_id).name}</b><small>${naira(b.booking_value)} referred revenue</small></div><strong>${naira(b.commission_amount)}</strong></article>`).join('')||'<div class="empty-state"><b>Nothing due</b>This week is fully settled.</div>'}</div><article class="clay-card statement-total"><span>Total commission due</span><b>${naira(due.reduce((n,b)=>n+b.commission_amount,0))}</b></article><button class="primary-btn" onclick="markWeeklySettlementPaid()">Mark settlement paid <span>✓</span></button>`)}else if(type==='addProperty'||type==='editProperty'){const p=id?propertyById(id):{};openCustom(propertyForm(p,id||0));initPropertyMap(p);bindPicturePreview()}else if(type==='membershipCard'){openMembershipCard()}else openCustom(`<h2 class="sheet-title">${type.replace(/([A-Z])/g,' $1')}</h2><p class="sheet-copy">This interface is connected and ready for its Supabase workflow.</p><button class="primary-btn" onclick="closeSheet()">Done <span>✓</span></button>`)}
const openSheetBase=openSheet;
openSheet=(type,id)=>{if(type!=='newReferredStay')return openSheetBase(type,id);const managerId=currentUser?.id||'m1',properties=sample.properties.filter(property=>property.manager_id===managerId);openCustom(`<h2 class="sheet-title">Open referred stay</h2><p class="sheet-copy">Record the guest, permanent Ambassador code and money actually received by the hotel.</p>${properties.length?`<form class="form-grid" onsubmit="saveNewStay(event)"><label class="field">Permanent Ambassador code<input id="stayReferralCode" placeholder="e.g. TC-12AB34CD" required oninput="previewAmbassadorCode(this.value)"></label><div id="ambassadorCodePreview" class="code-preview">Enter a code to identify the Ambassador.</div><label class="field">Property<select id="stayProperty">${properties.map(property=>`<option value="${property.id}">${esc(property.name)}</option>`).join('')}</select></label><div class="form-two"><label class="field">Guest name<input id="stayGuestName" required></label><label class="field">Guest phone<input id="stayGuestPhone" required></label></div><div class="form-two"><label class="field">Check-in<input id="stayCheckIn" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label class="field">Initial nights<input id="stayNights" type="number" min="1" value="1" required></label></div><label class="field">Room / category<input id="stayRoom" placeholder="e.g. Executive Room" required></label><div class="form-two"><label class="field">Amount received now<input id="stayAmount" type="number" min="0" value="0" required></label><label class="field">Payment method<select id="stayMethod"><option>Cash</option><option>Hotel transfer</option><option>POS</option><option>Corporate account</option><option>Pay later</option></select></label></div><button class="primary-btn">Open referred stay <span>→</span></button></form>`:'<div class="empty-state"><b>Add a property first</b>A referred stay must belong to one of your active properties.</div>'}`)};
function propertyMapsUrl(property){const lat=Number(property.latitude),lng=Number(property.longitude),query=Number.isFinite(lat)&&Number.isFinite(lng)?`${lat},${lng}`:property.address||propertyPlace(property);return`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`}
function openPropertyMap(id){const property=propertyById(id);if(!property)return;const opened=window.open(propertyMapsUrl(property),'_blank','noopener,noreferrer');if(opened)opened.opener=null}
function initPropertyDetailMap(property){setTimeout(()=>{const element=$('#propertyDetailMap');if(!element||!window.L)return;const lat=Number(property.latitude),lng=Number(property.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lng))return;propertyDetailMap=L.map(element,{scrollWheelZoom:false}).setView([lat,lng],16);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(propertyDetailMap);L.marker([lat,lng]).addTo(propertyDetailMap).bindPopup(`<b>${esc(property.name)}</b><br>${esc(property.address||property.location)}`).openPopup();setTimeout(()=>propertyDetailMap.invalidateSize(),100)},80)}
function openPropertyDetails(id){const property=propertyById(id);if(!property)return toast('Property not found');const hasCoordinates=Number.isFinite(Number(property.latitude))&&Number.isFinite(Number(property.longitude));openCustom(`<article class="property-detail-hero" style="background-image:linear-gradient(180deg,transparent 25%,rgba(14,23,43,.86)),url('${esc(property.image)}')"><span>${Number(property.commission_rate||0)}% AMBASSADOR COMMISSION</span><div><h2>${esc(property.name)}</h2><p>★ ${Number(property.rating||0).toFixed(1)} • From ${naira(property.price)} / night</p></div></article><div class="property-detail-location"><div class="detail-location-icon">⌖</div><div><small>EXACT PROPERTY LOCATION</small><h3>${esc(property.location||property.city)}</h3><p>${esc(property.address||propertyPlace(property))}</p><span>${esc(property.lga||property.city)} LGA • ${esc(property.state)}</span></div></div><div id="propertyDetailMap" class="property-detail-map ${hasCoordinates?'':'map-unavailable'}">${hasCoordinates?'':'Exact coordinates have not been added yet.'}</div><div class="coordinate-strip"><span><small>LATITUDE</small><b>${hasCoordinates?Number(property.latitude).toFixed(6):'Pending'}</b></span><span><small>LONGITUDE</small><b>${hasCoordinates?Number(property.longitude).toFixed(6):'Pending'}</b></span></div><div class="map-actions"><button class="primary-btn" type="button" onclick="openPropertyMap(${property.id})" ${hasCoordinates?'':'disabled'}>Open exact pin in Maps <span>↗</span></button><button class="soft-btn" type="button" onclick="openSheet('referralCode',${property.id})">Share my code</button></div><section class="property-detail-info"><h3>At this property</h3><div class="amenity-line">${(property.amenities||[]).map(item=>`<span>${esc(item)}</span>`).join('')}</div>${property.description?`<p>${esc(property.description)}</p>`:''}</section>`);if(hasCoordinates)initPropertyDetailMap(property)}
window.openSheet=openSheet;window.openPropertyDetails=openPropertyDetails;window.openPropertyMap=openPropertyMap;window.resetPropertyFilters=resetPropertyFilters;window.syncPropertyLgas=syncPropertyLgas;window.toast=toast;
window.submitBooking=(e)=>{e.preventDefault();openReferralCode()};
window.updateWithdrawalSummary=value=>{const amount=Math.max(0,Number(value||0));if($('#withdrawRequest'))$('#withdrawRequest').textContent=naira(amount);if($('#withdrawReceive'))$('#withdrawReceive').textContent=naira(amount)};
window.copyTransactionReference=async reference=>{await navigator.clipboard?.writeText(reference);toast('Transaction reference copied')};
window.downloadTransactionReceipt=async reference=>{const receipt=$('#transactionReceipt');if(!receipt)return;if(!window.html2canvas)return toast('Receipt export is still loading');const canvas=await html2canvas(receipt,{scale:3,backgroundColor:null});const link=document.createElement('a');link.href=canvas.toDataURL('image/png');link.download=`the-commission-${reference}.png`;link.click()};
window.downloadWalletReport=()=>{const csvCell=value=>`"${String(value??'').replace(/"/g,'""')}"`,rows=[['Reference','Date','Title','Description','Type','Status','Amount'],...sample.transactions.map(t=>[t.id,t.date,t.title,t.description,transactionTypeLabel(t.type),t.status,t.amount])],csv=rows.map(row=>row.map(csvCell).join(',')).join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='the-commission-wallet-report.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)};
window.savePayoutAccount=async e=>{e.preventDefault();const bank=$('#payoutBank').value,accountNumber=$('#payoutNumber').value.replace(/\D/g,''),accountName=$('#payoutName').value.trim();if(accountNumber.length!==10)return toast('Enter a valid 10-digit account number');if(accountName.length<3)return toast('Enter the account name');const payload={bank_name:bank,bank_account_number:accountNumber,bank_account_name:accountName},u=activeUser();if(sb){const{error}=await sb.from('profiles').update(payload).eq('id',u.id);if(error)return toast(error.message)}syncUser(payload);renderProfile();closeSheet();toast('Payout account saved')};
window.saveProfile=async e=>{e.preventDefault();const u=activeUser(),payload={full_name:$('#editFullName').value.trim(),city:$('#editCity').value.trim()};if(payload.full_name.split(/\s+/).length<2)return toast('Enter your full name');if(sb){const{error}=await sb.from('profiles').update(payload).eq('id',u.id);if(error)return toast(error.message)}syncUser(payload);$('#headerName').textContent=payload.full_name.split(' ')[0];$('#headerAvatar').textContent=initials(payload.full_name);renderProfile();closeSheet();toast('Profile updated')};
window.submitWithdrawal=async e=>{e.preventDefault();const u=activeUser(),amount=Number($('#withdrawAmount').value);if(amount<1000)return toast('Minimum withdrawal is ₦1,000');if(amount>Number(u.balance))return toast('Amount exceeds your available balance');let reference=`WDR-${Math.random().toString(36).slice(2,8).toUpperCase()}`,remainingBalance=Number(u.balance)-amount;if(sb){const{data,error}=await sb.rpc('request_withdrawal',{requested_amount:amount}).single();if(error)return toast(error.message);reference=`WDR-${data.withdrawal_id}`;remainingBalance=Number(data.remaining_balance)}syncUser({balance:remainingBalance});sample.transactions.unshift({id:reference,title:`${u.bank_name} withdrawal`,description:'Withdrawal request submitted',amount:-amount,type:'withdrawal',date:new Date().toLocaleString('en-NG',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}),status:'pending',method:'Bank transfer'});closeSheet();renderAll();toast('Withdrawal request submitted')};
window.saveProperty=async(e,id)=>{e.preventDefault();const existing=id?propertyById(id):null,files=[...($('#propPictures')?.files||[])],amenities=$$('input[name="amenities"]:checked').map(input=>input.value),incentives=$$('input[name="incentives"]:checked').map(input=>input.value),extra_incentives=$$('input[name="extraIncentive"]').map(input=>input.value.trim()).filter(Boolean),min_price=Number($('#propMinPrice').value),max_price=Number($('#propMaxPrice').value),latitude=Number($('#propLat').value),longitude=Number($('#propLng').value),submitButton=e.submitter||e.currentTarget.querySelector('button[type="submit"],button.primary-btn'),submitCopy=submitButton?.innerHTML;try{validatePropertyPictureFiles(files)}catch(error){return toast(error.message)}if(max_price<min_price)return toast('Maximum price must be higher than minimum price');if(!Number.isFinite(latitude)||!Number.isFinite(longitude))return toast('Place the exact property pin on the map');let uploaded={paths:[],urls:[]};if(submitButton){submitButton.disabled=true;submitButton.innerHTML=files.length?'Uploading photos… <span>↑</span>':'Saving property… <span>…</span>'}try{if(sb&&files.length)uploaded=await uploadPropertyPictures(files);const existingPictures=propertyPictureUrls(existing||{}),localPictures=!sb&&files.length?files.map(file=>URL.createObjectURL(file)):[],pictures=files.length?(sb?[...uploaded.urls,...existingPictures]:localPictures):existingPictures,payload={name:$('#propName').value.trim(),city:$('#propCity').value.trim(),state:$('#propState').value,lga:$('#propLga').value,location:$('#propLocation').value.trim(),address:$('#propAddress').value.trim(),description:$('#propDescription').value.trim(),rooms:Number($('#propRooms').value),min_price,max_price,price:min_price,commission_rate:Number($('#propRate').value),amenities,incentives,incentive:incentives[0]||extra_incentives[0]||'',extra_incentives,latitude,longitude,pictures,image:pictures[0]||existing?.image||'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80'};if(sb){const databasePayload={name:payload.name,city:payload.city,state:payload.state,lga:payload.lga,location:payload.location,address:payload.address,description:payload.description,min_price,max_price,rooms:payload.rooms,commission_rate:payload.commission_rate,amenities,incentives,extra_incentives,pictures,latitude,longitude,is_active:true};if(!id)databasePayload.manager_id=currentUser?.id;let result=id?await sb.from('properties').update(databasePayload).eq('id',id).select().single():await sb.from('properties').insert(databasePayload).select().single();if(result.error&&/lga|location|address|schema cache/i.test(result.error.message||'')){const compatiblePayload={...databasePayload,description:propertyDescriptionPayload(payload)};delete compatiblePayload.lga;delete compatiblePayload.location;delete compatiblePayload.address;result=id?await sb.from('properties').update(compatiblePayload).eq('id',id).select().single():await sb.from('properties').insert(compatiblePayload).select().single()}if(result.error){await removeUploadedPropertyPictures(uploaded.paths);return toast(result.error.message)}const saved=hydrateProperty(result.data);if(id)Object.assign(existing,saved);else sample.properties.unshift(saved)}else if(id)Object.assign(existing,payload);else sample.properties.unshift({id:Date.now(),manager_id:currentUser?.id||'m1',rating:0,occupancy:0,...payload});closeSheet();renderAll();toast(id?'Property, photos and exact location updated':'Property published with photos and exact location')}catch(error){console.error('Property save failed',error);toast(propertyUploadError(error))}finally{if(submitButton?.isConnected){submitButton.disabled=false;submitButton.innerHTML=submitCopy}}};
window.saveReferralBooking=(e,id)=>{e.preventDefault();const r=sample.referrals.find(x=>x.id===id),p=propertyById(r.property_id),value=+$('#refValue').value,rate=+$('#refRate').value;r.status='converted';sample.bookings.unshift({id:Date.now(),property_id:r.property_id,ambassador:r.ambassador,guest_name:r.guest_name,guest_phone:r.guest_phone,check_in:'2026-08-05',nights:1,booking_value:value,commission_amount:value*rate/100,status:'confirmed',code:$('#confirmCode').value});closeSheet();renderAll();toast('Referral converted to booking')};
window.updateBooking=updateBooking;window.convertReferral=convertReferral;window.closeSheet=closeSheet;
function addIncentiveField(){const wrap=$('#extraIncentives');const label=document.createElement('label');label.className='field removable-field';label.innerHTML='Other incentive<input name="extraIncentive" placeholder="e.g. Free airport pickup"><button type="button" onclick="this.parentElement.remove()">×</button>';wrap.appendChild(label)}
function bindPicturePreview(){const input=$('#propPictures'),preview=$('#picturePreview'),label=$('#pictureLabel');if(!input||!preview||!label)return;const existingMarkup=preview.innerHTML,existingCount=preview.querySelectorAll('img').length,originalLabel=label.textContent;let previewUrls=[];input.onchange=()=>{previewUrls.forEach(url=>URL.revokeObjectURL(url));previewUrls=[];const files=[...input.files];try{validatePropertyPictureFiles(files)}catch(error){input.value='';label.textContent=originalLabel;preview.innerHTML=existingMarkup;return toast(error.message)}label.textContent=files.length?`${files.length} new file(s) selected${existingCount?` • ${existingCount} existing`:''}`:originalLabel;previewUrls=files.map(file=>URL.createObjectURL(file));preview.innerHTML=previewUrls.map(url=>`<img src="${url}" alt="New property picture preview">`).join('')+existingMarkup}}
function useCurrentLocation(){if(!navigator.geolocation)return toast('GPS is not supported on this device');toast('Finding your location…');navigator.geolocation.getCurrentPosition(({coords})=>{const ll={lat:coords.latitude,lng:coords.longitude};if(propertyMap&&propertyMarker){propertyMap.setView([ll.lat,ll.lng],16);propertyMarker.setLatLng(ll)}$('#propLat').value=ll.lat.toFixed(6);$('#propLng').value=ll.lng.toFixed(6);toast('Location selected')},()=>toast('Location permission was not granted'))}
function copyReferralCode(){navigator.clipboard?.writeText((currentUser||sample.users.ambassador).referral_code);toast('Referral code copied')}
function referralShareText(){const u=currentUser||sample.users.ambassador;return `Book at any participating hotel and give reception my permanent referral code ${u.referral_code}. No guest account is required. View properties: https://thecommission.app/r/${u.referral_code}`}
function shareReferralWhatsApp(){window.open(`https://wa.me/?text=${encodeURIComponent(referralShareText())}`,'_blank')}
async function shareReferralNative(){if(navigator.share){await navigator.share({title:'The Commission',text:referralShareText()})}else{await navigator.clipboard?.writeText(referralShareText());toast('Referral link copied')}}
async function downloadMembershipCard(){const card=$('#membershipCard');if(!card)return;if(window.html2canvas){const canvas=await html2canvas(card,{scale:3,backgroundColor:null});const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download=`the-commission-${(currentUser||sample.users.ambassador).referral_code}.png`;a.click()}else toast('Card export library is still loading')}
window.addIncentiveField=addIncentiveField;window.useCurrentLocation=useCurrentLocation;window.copyReferralCode=copyReferralCode;window.shareReferralWhatsApp=shareReferralWhatsApp;window.shareReferralNative=shareReferralNative;window.downloadMembershipCard=downloadMembershipCard;

function ambassadorFromCode(code){const clean=String(code||'').trim().toUpperCase();const known={'TC-SARKI-204':'Sarki Amada','TC-AISHA-118':'Aisha Bello','TC-USMAN-412':'Usman Ali','TC-GRACE-901':'Grace Timothy'};return known[clean]||null}
function dbPaymentMethod(value){return String(value||'cash').trim().toLowerCase().replace(/\s+/g,'_')}
let referralLookupSequence=0;
window.previewAmbassadorCode=async value=>{const box=$('#ambassadorCodePreview'),code=String(value||'').trim().toUpperCase(),sequence=++referralLookupSequence;if(!box)return;if(code.length<5){box.className='code-preview';box.textContent='Enter a code to identify the Ambassador.';return}if(!sb){const name=ambassadorFromCode(code);box.className='code-preview '+(name?'valid':'');box.innerHTML=name?`✓ Verified Ambassador: <b>${esc(name)}</b>`:'Referral code was not found.';return}box.className='code-preview';box.textContent='Checking Ambassador code…';const{data,error}=await sb.rpc('lookup_ambassador_by_referral_code',{referral_number:code});if(sequence!==referralLookupSequence)return;const ambassador=Array.isArray(data)?data[0]:data;box.className='code-preview '+(ambassador&&!error?'valid':'');box.innerHTML=ambassador&&!error?`✓ Verified Ambassador: <b>${esc(ambassador.full_name)}</b>`:'Referral code was not found.'}
window.saveNewStay=async e=>{e.preventDefault();const code=$('#stayReferralCode').value.trim().toUpperCase(),pid=Number($('#stayProperty').value),p=propertyById(pid),amount=Number($('#stayAmount').value||0),method=$('#stayMethod').value,nights=Number($('#stayNights').value);if(sb){const{error}=await sb.rpc('open_referred_stay',{p_property_id:pid,p_referral_code:code,p_guest_name:$('#stayGuestName').value,p_guest_phone:$('#stayGuestPhone').value,p_check_in:$('#stayCheckIn').value,p_nights:nights,p_room_name:$('#stayRoom').value,p_initial_amount:amount,p_payment_method:dbPaymentMethod(method)});if(error)return toast(error.message);closeSheet();await loadLiveData();renderAll();return toast('Referred stay opened and saved')}const ambassador=ambassadorFromCode(code);if(!ambassador)return toast('Referral code was not found');sample.bookings.unshift({id:Date.now(),property_id:pid,ambassador,referral_code:code,guest_name:$('#stayGuestName').value,guest_phone:$('#stayGuestPhone').value,check_in:$('#stayCheckIn').value,nights,room:$('#stayRoom').value,payments:amount>0?[{amount,method,note:'Initial payment'}]:[],booking_value:amount,commission_amount:amount*p.commission_rate/100,status:'active',settlement_status:'unsettled',code:'STAY-'+Math.random().toString(36).slice(2,6).toUpperCase()});closeSheet();renderAll();toast('Referred stay opened')}
window.saveStayPayment=async(e,id)=>{e.preventDefault();const b=sample.bookings.find(x=>x.id===id),p=propertyById(b.property_id),amount=Number($('#paymentAmount').value),method=$('#paymentMethod').value,note=$('#paymentNote').value||'Additional payment';if(sb){const{error}=await sb.rpc('add_stay_payment',{p_stay_id:id,p_amount:amount,p_payment_method:dbPaymentMethod(method),p_note:note});if(error)return toast(error.message);closeSheet();await loadLiveData();renderAll();return toast('Payment saved to the stay')}b.payments.push({amount,method,note});b.booking_value=b.payments.reduce((n,x)=>n+Number(x.amount||0),0);b.commission_amount=b.booking_value*p.commission_rate/100;closeSheet();renderAll();toast('Payment added to stay')}
window.saveStayExtension=async(e,id)=>{e.preventDefault();const b=sample.bookings.find(x=>x.id===id),p=propertyById(b.property_id),n=Number($('#extensionNights').value),amount=Number($('#extensionAmount').value||0),method=$('#extensionMethod').value;if(sb){const{error}=await sb.rpc('extend_referred_stay',{p_stay_id:id,p_nights:n,p_amount:amount,p_payment_method:dbPaymentMethod(method)});if(error)return toast(error.message);closeSheet();await loadLiveData();renderAll();return toast(`Stay extended by ${n} night(s)`)}b.nights+=n;if(amount>0)b.payments.push({amount,method,note:`${n}-night extension`});b.booking_value=b.payments.reduce((t,x)=>t+Number(x.amount||0),0);b.commission_amount=b.booking_value*p.commission_rate/100;closeSheet();renderAll();toast(`Stay extended by ${n} night(s)`)}
window.completeStay=async id=>{const b=sample.bookings.find(x=>x.id===id);if(!b)return;if(sb){const{error}=await sb.rpc('complete_referred_stay',{p_stay_id:id});if(error)return toast(error.message);await loadLiveData();renderAll();return toast('Stay completed; commission is due Friday')}b.status='completed';b.settlement_status='due';renderAll();toast('Stay completed; commission added to weekly settlement')}
window.markWeeklySettlementPaid=async()=>{if(sb){const{data,error}=await sb.rpc('mark_manager_settlements_paid');if(error)return toast(error.message);closeSheet();await loadLiveData();renderAll();return toast(`${Number(data?.stays||0)} stay settlement(s) marked paid`)}sample.bookings.filter(b=>b.status==='completed'&&b.settlement_status==='due').forEach(b=>b.settlement_status='paid');closeSheet();renderAll();toast('Weekly commission settlement marked paid')}
function syncSignupReferralField(){const field=$('#signupReferralField'),input=$('#signupReferralNumber'),planField=$('#signupPlanField'),isAmbassador=$('#signupRole').value==='ambassador';field.classList.toggle('hidden',!isAmbassador);planField.classList.toggle('hidden',!isAmbassador);if(!isAmbassador)input.value='';else setSignupPlan(selectedMembershipPlan)}
function bind(){$('#modeLabel').textContent=demo?'Demo Mode':'Supabase Live';$('.demo-options').classList.toggle('hidden',!demo);$('#authNote').textContent=demo?'Both demo accounts use sample data.':'Securely connected to Supabase.';$('#signinForm').addEventListener('submit',signIn);$('#signupForm').addEventListener('submit',signUp);$('#demoAmbassador').onclick=()=>{if(demo)roleLogin('ambassador')};$('#demoManager').onclick=()=>{if(demo)roleLogin('manager')};$$('[data-auth-tab]').forEach(b=>b.onclick=()=>selectAuthTab(b.dataset.authTab));document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav)navigate(nav.dataset.nav);const op=e.target.closest('[data-open]');if(op)openSheet(op.dataset.open)});$('#closeSheet').onclick=closeSheet;$('#sheetBackdrop').onclick=closeSheet;const signOut=async()=>{if(sb)await sb.auth.signOut();localStorage.removeItem('tc-role');location.reload()};$('#logoutBtn').onclick=signOut;$('#quickLogout').onclick=signOut;let balancesVisible=true;$('#toggleBalance').onclick=()=>{balancesVisible=!balancesVisible;const value=balancesVisible?naira(activeUser().balance):'₦ ••••••';$('#balanceValue').textContent=value;$('#walletBalance').textContent=value;$('#toggleBalance').textContent=balancesVisible?'◉':'○';$('#toggleBalance').setAttribute('aria-label',balancesVisible?'Hide balances':'Show balances')};$('#propertySearch').oninput=e=>{const q=e.target.value.toLowerCase();renderPropertyList(sample.properties.filter(p=>[p.name,p.city,p.state,...p.amenities].join(' ').toLowerCase().includes(q)))};$('#clearSearch').onclick=()=>{$('#propertySearch').value='';renderPropertyList(sample.properties)};const cities=['All',...new Set(sample.properties.map(p=>p.city))];$('#cityFilters').innerHTML=cities.map((c,i)=>`<button class="${i?'':'active'}">${c}</button>`).join('');$$('#cityFilters button').forEach(b=>b.onclick=()=>{$$('#cityFilters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderPropertyList(b.textContent==='All'?sample.properties:sample.properties.filter(p=>p.city===b.textContent))});$('#managerPropertySearch').oninput=e=>renderManagerProperties(sample.properties.filter(p=>p.manager_id===(currentUser?.id||'m1')&&p.name.toLowerCase().includes(e.target.value.toLowerCase())));$('#clearManagerPropertySearch').onclick=()=>{$('#managerPropertySearch').value='';renderManagerProperties(sample.properties.filter(p=>p.manager_id===(currentUser?.id||'m1')))};$$('#bookingFilters button').forEach(b=>b.onclick=()=>{$$('#bookingFilters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderManagerBookings(b.dataset.status==='all'?sample.bookings:sample.bookings.filter(x=>x.status===b.dataset.status))});$('#zoomIn').onclick=()=>{treeScale=Math.min(1.35,treeScale+.1);applyTreeTransform()};$('#zoomOut').onclick=()=>{treeScale=Math.max(.35,treeScale-.1);applyTreeTransform()};$('#zoomReset').onclick=$('#fitTree').onclick=()=>{treeScale=window.innerWidth<600?.42:.72;treeOffset={x:0,y:0};applyTreeTransform()};const vp=$('#treeViewport');vp.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,ox:treeOffset.x,oy:treeOffset.y};vp.setPointerCapture(e.pointerId)};vp.onpointermove=e=>{if(!drag)return;treeOffset.x=drag.ox+e.clientX-drag.x;treeOffset.y=drag.oy+e.clientY-drag.y;applyTreeTransform()};vp.onpointerup=()=>drag=null;vp.onpointercancel=()=>drag=null}
function bindPropertySearch(){const search=$('#propertySearch'),state=$('#propertyStateFilter'),lga=$('#propertyLgaFilter'),location=$('#propertyLocationFilter');search.oninput=event=>{propertyFilters.query=event.target.value.trim();applyPropertyFilters()};$('#clearSearch').onclick=()=>{propertyFilters.query='';search.value='';applyPropertyFilters()};state.onchange=event=>{propertyFilters.state=event.target.value;propertyFilters.lga='';propertyFilters.location='';refreshLgaAndLocationOptions();applyPropertyFilters()};lga.onchange=event=>{propertyFilters.lga=event.target.value;propertyFilters.location='';refreshLgaAndLocationOptions();applyPropertyFilters()};location.onchange=event=>{propertyFilters.location=event.target.value;applyPropertyFilters()};$('#resetPropertyFilters').onclick=resetPropertyFilters;$('#clearLocationFilters').onclick=resetPropertyFilters}
function handleHomepageRequest(request){if(request?.type==='tc-route'){pendingAppRoute=request.route==='properties'?'properties':null;if(currentUser){showApp();return}openAuth(request.mode||'signup',request.plan||'standard');return}if(request?.type==='tc-auth'){pendingAppRoute=null;if(currentUser){showApp();if(currentRole==='ambassador')openSheet('membershipCard');return}openAuth(request.mode||'signup',request.plan||selectedMembershipPlan)}}
bind();bindDigitsOnlyInput($('#signinPhone'));bindDigitsOnlyInput($('#signupPhone'));$('#authBack').onclick=showPublicHomepage;$('#signupRole').onchange=syncSignupReferralField;$('#signupPlan').onchange=event=>setSignupPlan(event.target.value);$('#signupReferralNumber').oninput=event=>event.target.value=event.target.value.toUpperCase();window.addEventListener('tc-platform-request',event=>handleHomepageRequest(event.detail));syncSignupReferralField();setSignupPlan(selectedMembershipPlan);bindPropertySearch();$('#socialProofClose').onclick=dismissSocialProof;loadSocialProofs();loadHomepageContent();$('#authNote').textContent=demo?'Both demo accounts use sample data.':'Checking password-only Auth settings…';passwordSettingsPromise=checkPasswordOnlySettings();restoreSession();
